window.SAQ_PAPER_QUESTIONS["2026-1-pah"]=[{"number":1,"title":"","stemText":"A 32 year old pregnant woman has presented with lower abdominal pain and vaginal bleeding. Her\nlast menstrual period was 10 weeks ago.\nYou are concerned about the possibility of ectopic pregnancy. 1.\nState 5 features of your history or examination that would make the diagnosis of ectopic\npregnancy more likely than miscarriage. (5 marks) 2.\nState 4 ultrasound findings that would be consistent with ectopic pregnancy. (4 marks)","parts":[{"id":"p3","label":"Part 3","prompt":"List and justify 3 investigations (apart from USS) you will perform. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Haemodynamic compromise</div><div class=\"answer-line\">Lateralising pain - Hx</div><div class=\"answer-line\">Peritonism</div><div class=\"answer-line\">Adnexal mass on bimanual examination</div><div class=\"answer-line\">Shoulder tip pain – Hx</div><div class=\"answer-line\">Sudden onset constant pain – Hx</div><div class=\"answer-line\">Previous ectopic</div><div class=\"answer-line\">Tubal surgery</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">Empty uterus</div><div class=\"answer-line\">Adnexal mass</div><div class=\"answer-line\">IP free blood</div><div class=\"answer-line\">Extra uterine cardiac activity</div><div class=\"answer-line\">Tubal ring sign</div><div class=\"answer-line\">Pseudo-gestational sac</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">VBG – determine degree shock / extent of resus required</div><div class=\"answer-line\"><strong>G+H</strong>/X-match – for specific blood transfusion if required</div><div class=\"answer-line\">Rh status – requirement for anti-D</div><div class=\"answer-line\">Hb – degree blood loss / requirement for transfusion</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 20 day old girl has been brought to the ED with fever and poor feeding. Following your initial assessment, you have a high suspicion of meningitis as the cause of the presentation.","parts":[{"id":"p1","label":"Part 1","prompt":"List 3 organisms that commonly cause meningitis in this age group. (3 marks)\nThe child looks pale and has the following vital signs:\n\nHR\n180 /min\n\nBP\n70/35 mmHg\n\nCap refill\nseconds\n\nRR\n/min O2 sats 99% room air Temperature 39.0 degrees\n\nBSL\n2.0 mmol/L"},{"id":"p2","label":"Part 2","prompt":"State 3 components of your initial management. (3 marks)\nYou are considering performing a lumbar puncture."},{"id":"p3","label":"Part 3","prompt":"List and justify 3 other investigations you would perform. (3 marks)"},{"id":"p4","label":"Part 4","prompt":"List 3 potential contra-indications to performing a lumbar puncture in this child. (3 marks) Lumbar puncture was performed. The CSF result is provided below. CSF WBC 1510 *10^6/L (<15)\nPolymorphs 96%\nMononuclears 4%\nRBC 210 *10^6/L (<10)\n\nGlucose\n0.5 mmol/L (1.5 - 5.5) Protein 1550 mg/L (200 - 1000)"},{"id":"p5","label":"Part 5","prompt":"Interpret the result. (3 marks)"},{"id":"p6","label":"Part 6","prompt":"List 3 potential complications of this condition. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">E coli</div><div class=\"answer-line\">Group B Strep</div><div class=\"answer-line\">Listeria monocytogenes</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>N/S 10mL/kg IV aiming for BP 70-80 / cap refill &lt;3s repeat if required </strong></div><div class=\"answer-line\"><strong>Benpen IV 60mg/kg, cefotaxime 50mg/kg IV </strong></div><div class=\"answer-line\">BC – isolate pathogen for downstream AB rationalisation</div><div class=\"answer-line\">VBG – define degree shock – guide resus</div><div class=\"answer-line\">Urine M/C/S – common source sepsis – guide Rx</div><div class=\"answer-line\">FBC – exclude low plts before LP (eg part of DIC)</div><div class=\"answer-line\">Coag – if DIC suspected</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">BC – isolate pathogen for downstream AB rationalisation</div><div class=\"answer-line\">VBG – define degree shock – guide resus</div><div class=\"answer-line\">Urine M/C/S – common source sepsis – guide Rx</div><div class=\"answer-line\">FBC – exclude low plts before LP (eg part of DIC)</div><div class=\"answer-line\">Coag – if DIC suspected</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Falling GCS / obtunded</div><div class=\"answer-line\">Signs raised ICP – eg pupillary abnormalities</div><div class=\"answer-line\">Infection at site</div><div class=\"answer-line\">Focal neuro signs / seizures</div><div class=\"answer-line\">INR &gt;1.5, low plts</div></section><section class=\"answer-part\"><h5>Part 5</h5><div class=\"answer-line\">Bacterial meningitis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Raised WBCS – mostly neutrophils</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Low glucose/ raised protein</div></section><section class=\"answer-part\"><h5>Part 6</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Multi-organ involvement due to primary pathogen or secondary to septic shock</td></tr><tr><td>•</td><td>Venous sinus thrombosis</td></tr><tr><td>•</td><td>Hydrocephalus</td></tr><tr><td>•</td><td>Seizures, subsequent epilepsy</td></tr><tr><td>•</td><td>Hearing impairment</td></tr><tr><td>•</td><td>Neurodevelopmental impairment</td></tr><tr><td>•</td><td>Permanent focal neurological deficit</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 25 year old man has been taken to the ED after an electric scooter accident.\nHis vital signs on arrival are:\n\nGCS\nE3 V4 M5 Pulse 150 /min\n\nBP\n65/40 mmHg\n\nRR\n/min O2 sats 99% room air Chest x-ray and pelvic x-ray are both normal. The right upper quadrant view from his FAST scan is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe and interpret the image. (2 marks)"},{"id":"p2","label":"Part 2","prompt":"Provide 3 features of your blood product resuscitation strategy. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"Provide 2 pros and 2 cons to performing CT on this patient. (4 marks)"},{"id":"p4","label":"Part 4","prompt":"List 3 potential complications of blood product resuscitation you might encounter in the\nED. (3 marks)"}],"propPages":["asset:imgd442860fe1744659ab"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Positive FAST scan with perihepatic blood and blood in Morrison’s pouch</div><div class=\"answer-line\">Intra-peritoneal blood, will require intervention (surgical / IR)</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Permissive hypotension – aim BP 80 systolic</div><div class=\"answer-line\">ROTEM to guide fibrinogen / FFP / platelet use</div><div class=\"answer-line\">Others ok</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Pros</td></tr><tr><td>-</td><td>Identify other injuries requiring management eg head injury</td></tr><tr><td>-</td><td>May identify blush that can be managed with IR instead of OT</td></tr><tr><td colspan=\"2\">Cons</td></tr><tr><td>-</td><td>Time – if too unstable might risk further bleeding / hypotension /death</td></tr><tr><td>-</td><td>Contrast administration – risk allergy / C/I if allergy</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Coagulopathy</div><div class=\"answer-line\">Low calcium</div><div class=\"answer-line\">Allergic blood transfusion reaction</div><div class=\"answer-line\">Febrile reaction</div><div class=\"answer-line\">ABO incompatibility</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 2 month old boy has been brought to the ED by her mother.\nFollowing your assessment, you have diagnosed the child with bronchiolitis.","parts":[{"id":"p1","label":"Part 1","prompt":"Provide 3 indications for admission to an inpatient ward. (3 marks)\nYou have recommended that the child be admitted to an inpatient ward for ongoing management. The child’s mother has become extremely agitated and wants to leave with the child against your advice."},{"id":"p2","label":"Part 2","prompt":"State 3 features of your assessment of the mother to determine her competence to make\ndecisions on her daughter’s behalf. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"Apart from the mother’s competence, state 3 factors you will consider in deciding whether you will allow the mother to take the child from the ED. (3 marks) You have determined that the child must stay in the hospital, despite the mother’s intent to take him home. The mother is both verbally and physically abusive towards staff."},{"id":"p4","label":"Part 4","prompt":"State 3 components of your management of this situation. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Oxygen requirement – eg sats &lt;90%</div><div class=\"answer-line\">Apnoeas</div><div class=\"answer-line\">Unable to feed - &lt;50% normal feeds or dehydrated</div><div class=\"answer-line\">Specific risk factors for serious illness</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Understands medical condition</div><div class=\"answer-line\">Understands options for treatment</div><div class=\"answer-line\">Understands likely outcomes from each option</div><div class=\"answer-line\">Ability to make rational decisions</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Seriousness of child’s condition ie likely outcome of going home</div><div class=\"answer-line\">Natural progression of illness eg what day of illness</div><div class=\"answer-line\">Reason for wanting to leave - ?reasonable eg going to a private hospital or unreasonable</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Verbal de-escalation / explanation to parent</div><div class=\"answer-line\">Show of force – security staff</div><div class=\"answer-line\">Physical restraint – security staff</div><div class=\"answer-line\">Involvement child services/ police</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 2 year old girl has presented with vomiting and diarrhea of 2 days duration.\nYour clinical assessment is consistent with infectious gastro-enteritis.","parts":[{"id":"p1","label":"Part 1","prompt":"Complete the table regarding the discriminatory clinical features when assessing for severity of dehydration. (3 marks) Clinical features on assessment Mild dehydration Moderate dehydration Severe dehydration"},{"id":"p2","label":"Part 2","prompt":"List 4 investigations you might perform. Provide the indication for each. (4 marks)\nYou have decided that the child is suitable for rapid nasogastric rehydration."},{"id":"p3","label":"Part 3","prompt":"Provide the details of your rapid nasogastric rehydration regime. (3 marks)"},{"id":"p4","label":"Part 4","prompt":"List 2 indications for antibiotic therapy in this child. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>(8/12) </strong></div><div class=\"answer-line\">1.</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>BSL<strong> </strong>– poor intake, lethargy, exclude hypoglycaemia – all patients</td><td>Ketones – exclude/quantify starvation ketosis in moderate/severe dehydration</td></tr><tr><td>VBG – quantify degree acidosis in severe dehydration – target fluid Rx</td><td>BC – if septic to identify bacteria for targeted Rx</td></tr><tr><td>Stool culture – if septic/moderate/severely unwell to identify pathogen for targeted Rx</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">ORS any type</div><div class=\"answer-line\">10-25mL/kg/hr for 4 hours</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Septic</div><div class=\"answer-line\">Returned traveller</div><div class=\"answer-line\">Bloody diarrhea</div><div class=\"answer-line\">immunocompromised</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 17 year old female has presented with a painful, swollen right ear.\nA clinical photograph is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe and interpret the photograph. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 2 organisms that commonly cause this problem. (2 marks)"},{"id":"p3","label":"Part 3","prompt":"Provide 3 options for antibiotic therapy. For each, provide the indication for its use.\n(3 marks)"},{"id":"p4","label":"Part 4","prompt":"State 2 other components of your management. (2 marks)"}],"propPages":["asset:imge6f2a659d74345a137"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Pinna abscess, accept perichondritis</div><div class=\"answer-line\">Likely due to piercing given skin defects superior pinna and posterior</div><div class=\"answer-line\">Erythema pinna</div><div class=\"answer-line\">Swelling</div><div class=\"answer-line\">Distorted position (“pushed forward”)</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Staph aureus</div><div class=\"answer-line\">Pseudomonas aeruginosa</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>IV pip/taz 4.5g QID – 1st preference, covers Staph and Pseudomonas</td><td>IV ceftazidime/cefipime – if penicillin allergic</td></tr><tr><td>IV ciprofloxacin – severe penicillin allergy or oral if outpatient management</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Analgesia – eg paracetamol 1g QID, ibuprofen 400mg TDS, endone 5mg QID</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 25 year old man has been brought to the hospital by ambulance following a collapse in the community. He was thought to have sustained a seizure which spontaneously terminated after 5 minutes.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 features of your history that would suggest this episode to have been a functional\nseizure. (4 marks) Shortly after arrival, the patient has another episode of jerking movements."},{"id":"p2","label":"Part 2","prompt":"List 4 features of your examination that would support the diagnosis of functional\nseizures. (4 marks) Your history and examination are consistent with generalised tonic-clonic seizures. The patient has never had seizures previously. The seizure was terminated with intravenous midazolam. 3.\nList 5"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Known diagnosis FND</div><div class=\"answer-line\">Provoked by personal emotional issue</div><div class=\"answer-line\">Multitude of symptoms across many systems</div><div class=\"answer-line\">Symptoms of dissociation from bodily function</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Multiple deficits not anatomically relatable</td><td>Side to side head movements</td></tr><tr><td>Resisting eye opening</td><td>No post-ictal period</td></tr><tr><td>Recall for period of unresponsiveness</td><td>3.</td></tr><tr><td>Serum Na – cause seizure</td><td><strong>Glucose</strong> – cause seizure</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 25 year old woman has presented to ED after a syncopal episode in the community.\nOn arrival to the ED, she has no symptoms and normal vital signs.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 historical findings that would place her at high risk of a cardiac cause of syncope. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 features of your examination. Provide the relevance of each. (4 marks)\nHer ECG is provided below."},{"id":"p3","label":"Part 3","prompt":"Describe and interpret the ECG, including the clinical relevance. (4 marks)"}],"propPages":["asset:img27852d8bf92d393e1f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Family Hx SCD</div><div class=\"answer-line\">chest pain prior to onset</div><div class=\"answer-line\">Palpitations prior to onset</div><div class=\"answer-line\">during exercise</div><div class=\"answer-line\">known structural heart disease</div><div class=\"answer-line\">supine</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Murmurs of outflow tract obstruction eg AS, HOCM</div><div class=\"answer-line\">Injuries from syncope eg head injury</div><div class=\"answer-line\">Postural BP – looking for postural hypotension as cause</div><div class=\"answer-line\">Signs of intercurrent illness – eg low grade sepsis</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">LVH – massive QRS complexes meeting LVH criteria – S waves V1/2 + R waves V5/6 &gt;35mm</div><div class=\"answer-line\">Assoc repol abnormalities – discordant ST segments and T Waves</div><div class=\"answer-line\">HOCM</div><div class=\"answer-line\"><strong>Needs admission for tele / echo </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 45 year old man has re-presented with a painful right knee.\nHe was seen the day prior after injuring his knee while playing basketball with his children. He was diagnosed with a knee sprain and was sent home with crutches. He has been unable to manage his pain. His x-ray is provided below. 1. Describe and interpret the x-ray. (3 marks) 2.\nState 3 components of your management of this injury. (3 marks)\nThe patient is upset about the situation and has made a formal complaint.","parts":[{"id":"p3","label":"Part 3","prompt":"State 6 components of your management of this situation. (6 marks)"}],"propPages":["asset:img33beea308deddc05bf"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">High riding patella</div><div class=\"answer-line\">Avulsion fracture inferior patella</div><div class=\"answer-line\">Patella tendon rupture</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">Analgesia – something appropriate</div><div class=\"answer-line\">Richard’s splint / crutches NWB</div><div class=\"answer-line\">Ortho admission for operation to fix</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Apologise</div><div class=\"answer-line\">Discuss process with patient</div><div class=\"answer-line\">Review case</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Review notes</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Discuss with doctors involved</div><div class=\"answer-line\">Review processes</div><div class=\"answer-line\">Enact change if required</div><div class=\"answer-line\">Respond to patient</div><div class=\"answer-line\">Also accept medico-legal team notification</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 57 year old man has presented after falling from standing height.\nHe is complaining of a headache with no other apparent injuries. He is on rivaroxaban for AF. 1.","parts":[{"id":"p1","label":"Part 1","prompt":"List 5 situations in which the Canadian CT Head rule is not applicable. (5 marks)\nOne slice from the patient’s non-contrast CT head is shown below. 2."},{"id":"p2","label":"Part 2","prompt":"Describe the abnormalities on the CT scan. (3 marks) 3.\nList 4 medications you might administer in the ED (excluding intubation drugs). Provide\njustification for each. (4 marks)"}],"propPages":["asset:img8528da972f352fb637"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Non-trauma cases</div><div class=\"answer-line\">GCS &lt;13</div><div class=\"answer-line\">Age &lt;16</div><div class=\"answer-line\">Warfarin or bleeding disorder</div><div class=\"answer-line\">Obvious open skull fracture</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Medication</th><th>Justification</th></tr></thead><tbody><tr><td>Convex hyperdensity left side</td><td>Midline shift towards right</td></tr><tr><td>Active bleeding as evidenced by hypodense core of epidural haematoma</td><td>3.</td></tr><tr><td>- Analgesia – IV opiates</td><td>- Keppra (20mg/kg) – Seizure prophylaxis or treatment</td></tr><tr><td>- Hypertonic saline (250mL or 3mL/kg 3% saline) targeting Na 150-155 – Drop in GCS by 2 or more</td><td>points, blown pupil, bilateral dilated pupils, new focal motor deficit, Cushing’s response (OR</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 14 year old girl has presented with her parents 4 hours after a deliberate self-poisoning of immediate-release iron polymaltose. It is unclear how many tablets she has taken. She is complaining of abdominal pain and vomiting with haematemesis. 1.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 blood tests you would perform, including justification. (4 marks)\nAn x-ray of her abdomen is provided below. 2."},{"id":"p2","label":"Part 2","prompt":"Describe and interpret the x-ray. (3 marks) 3."},{"id":"p3","label":"Part 3","prompt":"Describe your approach to decontamination. (2 marks) The patient has the following vital signs:\n\nGCS\n\nHR\n130 /min\n\nBP\n70/40 mmHg\n\nRR\n/min\n\nSpO2\n99% room air\n\nTemp\n36.5 degrees 4."},{"id":"p4","label":"Part 4","prompt":"State 3 other components of your management. (3 marks)"}],"propPages":["asset:img2b228666ad3e00fba4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">- Serum iron concentration at 4-6 hours: To determine likely severity of toxicity and indication for</div><div class=\"answer-line\">desferrioxamine if over 90mcg/L (don’t need concentration here for mark)</div><div class=\"answer-line\">- VBG: Identify HAGMA as indicator of severity of toxicity</div><div class=\"answer-line\">- Hb – GI bleeding – assess severity, need for transfusion</div><div class=\"answer-line\">- G+H – if transfusion required to replace Hb</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Large number of tablets in stomach – radio-opaque consistent with Fe</div><div class=\"answer-line\">Concerning for massive overdose</div><div class=\"answer-line\">Pharmacobezoar formation</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">endoscopic removal of tablets</div><div class=\"answer-line\">Then WBI – macrogol 25mL/kg/hr</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">IV N/S – 20mL/kg aiming for BP &gt;90mmHg</div><div class=\"answer-line\">Accept O neg packed cells 1 unit if large volume blood loss likely – aim systolic &gt;90mmHg</div><div class=\"answer-line\">Noradrenaline OK – infusion 5-50 mcg/min</div><div class=\"answer-line\">Desferrioxamine 15mg/kg/hr – in severe toxicity or level 90umol/L</div><div class=\"answer-line\">Analgesia/antiemetics (with dosing as long as reasonable)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 42 year old man has presented with severe tongue swelling.\nThe patient has biphasic stridor and is agitated. Following your assessment, you have concluded that the patient requires urgent airway management in the ED. 1. Complete the following table with 3 airway/breathing issues you may anticipate in this\ncase and 2 components of your management for each. (9 marks)\nAnticipated issue Management components The patient’s partner has arrived and states that the patient has hereditary angioedema.","parts":[{"id":"p2","label":"Part 2","prompt":"List 4 ways in which you could differentiate between anaphylaxis and hereditary\nangioedema clinically. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 specific treatment options in this case, including the mechanism of action for each. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Inability to pre-oxygenate</td><td>Ketamine boluses  10-20mg to settle</td><td></td></tr><tr><td colspan=\"3\">agitation</td></tr><tr><td>-</td><td>Pre-oxygenate with NIV once more</td><td></td></tr><tr><td colspan=\"3\">settled eg 16/8</td></tr><tr><td>Rapid desaturation</td><td>-</td><td>Use high flow O2 via nasal cannulae in</td></tr><tr><td colspan=\"3\">apnoeic period</td></tr><tr><td>-</td><td>Bag through apnoea</td><td></td></tr><tr><td>Difficulty passing tube due to swelling</td><td>-</td><td>Use VL</td></tr><tr><td>-</td><td>Low profile blade</td><td></td></tr><tr><td>-</td><td>Smaller ETT</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Course: Rapid onset (anaphylaxis) vs. gradual (HA)</td><td>Previous episodes of isolated angioedema</td></tr><tr><td>Multisystem hypotension, bronchospasm, rash with anaphylaxis vs. isolated angioedema in HA</td><td>Itchy: More likely anaphylaxis</td></tr><tr><td>Oedema appearance: well-demarcated, asymmetric, non-dependent (HA) vs. widespread,</td><td>symmetrical.</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 63 year old woman has presented with diarrhoea on the background of type 2 diabetes mellitus and chronic kidney disease (stage 5). She is dialysis dependent. Her arterial blood gas is provided below.\n\nABG\n\npH\n7.01 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (22 - 32)\n\nBE\n-23.7 mmol/L (-3.0 - 3.0)\n\nNa\n138 mmol/L (135 - 145)\n\nK\n3.8 mmol/L (3.5 - 5.2)\n\nCl\n116 mmol/L (95 - 110)\n\nGlucose\nmmol/L (3.0 - 7.8)\n\nLactate\n0.71 mmol/L (0.5 - 2.2)","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the ACID-BASE components of the blood gas. Include formulae you have used and the most likely cause of each abnormality. (9 marks) The patient has the following vital signs:\n\nGCS\n\nHR\n110 /min\n\nBP\n95/65 mmHg\n\nRR\n/min O2 sats 98% room air\n\nTemp\n37.5 degrees"},{"id":"p2","label":"Part 2","prompt":"State 3 treatments you might provide. Include the justification for each.\n(3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Critical acidaemia with raised anion gap (16), mixed NAGMA (delta 0.22) and incomplete respiratory</div><div class=\"answer-line\">compensation.</div><div class=\"answer-line\">1) AG = 138 – (116+5.8) = 16 – <strong>HAGMA</strong> – likely due to renal failure or ketones from</div><div class=\"answer-line\">starvation</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>HAGMA of 16 so must be mixed. NAGMA from HCO3 loss with diarrhoea</td><td>3) Expected CO2 = 1.5 x 5.8 + 8 = 17</td></tr><tr><td>Incomplete respiratory compensation due to pre-existing lung disease / sedating meds</td><td><strong>Essential to pass question: </strong></td></tr><tr><td><strong>2/3 Acid Base disturbance – one of these must be a HAGMA </strong></td><td><strong>2/3 Correct formulae  </strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You are intending to design a prospective trial around fluid resuscitation in sepsis.","parts":[{"id":"p1","label":"Part 1","prompt":"Outline 3 ways in which the effect of confounding variables can be minimised in\nprospective therapeutic clinical study design. (3 marks) Your review of the existing literature has included the FEAST trial. The FEAST trial performed in Africa was a landmark study which investigated the amount and rate of fluid resuscitation in children with presumed sepsis. Commentators have stated that external validity is a key concern in this paper."},{"id":"p2","label":"Part 2","prompt":"What is external validity? (1 mark) 3. State 4 issues in the interpretation of the results for a developed nation patient cohort. (4 marks) 4.\nWhat are 3 potential issues with a non-blinded study such as the FEAST trial? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Randomisation: participants are randomly assigned to treatment cohorts</div><div class=\"answer-line\">Baseline characteristics compared between groups prior to study initiation (and published)</div><div class=\"answer-line\">Multivariate analysis allows for confounding variable effects to be taken into account</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">The applicability of results of an experiment to a different population than that studied.</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Baseline variable comparison i.e. age, gender, body weight, severity of illness</div><div class=\"answer-line\">Would subsequent interventions performed in non-responders in developed nations significantly</div><div class=\"answer-line\">alter the studies primary endpoints? i.e. vasopressors, intubation, ICU-level care.</div><div class=\"answer-line\">What specific diagnoses were being treated (if known with accuracy) and were these similar to a</div><div class=\"answer-line\">developed nation cohort i.e. GI losses vs. malaria</div><div class=\"answer-line\">Were the results in particular subsets of children seen in developed nations (i.e. non-malarial</div><div class=\"answer-line\">children) similar and statistically significant?</div><div class=\"answer-line\">4.</div><div class=\"answer-line\">Hawthorn effect – Study participants (patients or clinicians) may alter their behaviour differently for</div><div class=\"answer-line\">patients in each arm of the trial</div><div class=\"answer-line\">Observer bias – Data collection is not blinded and may not be objective</div><div class=\"answer-line\">Performance bias – Systematic differences in care may occur apart from the intervention being</div><div class=\"answer-line\">studied</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 5 year old boy (20kg) has presented with increased work of breathing, fevers and lethargy. His chest x-ray is provided below. Describe and interpret the chest x-ray. (3 marks) 1.\nHis vital signs are as follows:\n\nHR\n140 /min\n\nBP\n70/30 mmHg\n\nRR\n/min\n\nSpO2\n85% 6L/min O2 via Hudson mask Temperature 38.8 degrees\n\nCap refill\nseconds He is lethargic and only responding to painful stimuli. You elect to intubate the child. Other than anti-microbials, state 3 treatment measures you would initiate in preparation 2. for intubation. (3 marks)","parts":[{"id":"p3","label":"Part 3","prompt":"List 5 anti-microbial drugs you might prescribe. Provide the clinical justification for each. (5 marks)"}],"propPages":["asset:img16054ac61f457d5fdb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Right upper and mid-zone patchy airspace consolidation with loss of right heart border consistent</td><td>with right upper and middle lobe <strong>pneumonia</strong>.</td></tr><tr><td>2.</td><td><strong>Fluids - </strong>IV N/saline 20mL/kg up to 60mL/kg targeting BP &gt;80 systolic, CRT &lt;2 seconds and improved</td></tr><tr><td>mentation</td><td>Adrenaline infusion (0.1mcg/kg/min) titrated to age-appropriate MAP target (5-50% of median) OR</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"An 8 year old boy has presented to the ED with a rash.\nA clinical photo is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 features of your history or examination that would make measles the likely\ndiagnosis. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 differential diagnoses. For each, provide a defining feature of your history or\nexamination. (6 marks) Differential diagnosis Defining feature of history or examination"},{"id":"p3","label":"Part 3","prompt":"List 2 investigations you could perform to confirm a measles infection. (2 marks)"}],"propPages":["asset:img72dac17bc09c749f2f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Not immunised</div><div class=\"answer-line\">Contact with measles</div><div class=\"answer-line\">Koplik spots</div><div class=\"answer-line\">Something about prodrome – cough, coryza, fever before rash</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Disease</td><td>Specific clinical feature</td></tr><tr><td>Scarlet fever</td><td>Sandpaper feeling</td></tr><tr><td>Co-existent or recent streptococcal pharyngitis</td><td></td></tr><tr><td>or impetigo</td><td></td></tr><tr><td>Kawasaki</td><td>Fever for 5 days with 4/5 other features for</td></tr><tr><td>confirmed case: Cervical lymph node, non-</td><td></td></tr><tr><td>purulent conjunctivitis, strawberry tongue,</td><td></td></tr><tr><td>desquamation, painful oedema hands/feet</td><td></td></tr><tr><td>Roseola infantum</td><td>Distribution: Trunk spreading to extremities</td></tr><tr><td>Erythema infectiosum</td><td>Slapped cheek appearance then spreading to</td></tr><tr><td>body</td><td></td></tr><tr><td>EBV/CMV</td><td>Splenomegaly, post-amoxicillin, tonsillitis</td></tr><tr><td>Rubella</td><td>Nothing specific except absence of Koplik spots</td></tr><tr><td>Enteroviruses</td><td>Recent diarrhoeal illness</td></tr><tr><td>Drug eruptions</td><td>Often associated with new medication</td></tr><tr><td>initiation</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Nasopharyngeal swab PCR</div><div class=\"answer-line\">IgM and IgG serology</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 7 year old boy has presented with a severely swollen anterior thigh after being hit by a cricket ball at training. It is an isolated injury. He is known to have Haemophila A.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 features of your history taking that will alter your subsequent treatment plan.\nProvide explanation for each. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List 4 features of your examination, including the significance of each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 medications you might use in this patient’s management. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Severity of haemophilia A – More likely to need clotting factor replacement and at higher doses</td><td>Pain out of proportion – Concern for compartment syndrome</td></tr><tr><td>Usual recombinant factor product of choice – Should receive the same brand/type if possible</td><td>Presence of factor inhibitors – Require special ‘bypass’ product to initiate clotting</td></tr><tr><td>Venesection/cannulation issues – May require sedation, USS-guidance, senior operator</td><td>Last dose of prophylaxis – may change need factor replacement / dose</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Pain on passive movement – Concern for compartment syndrome</div><div class=\"answer-line\">Absent distal pulses – Concern for neurovascular compromise from deep muscle involvement</div><div class=\"answer-line\">Distal capillary refill &gt;2 seconds – “</div><div class=\"answer-line\">Distal numbness – “</div><div class=\"answer-line\">Pulsatile mass in thigh – Concern for active arterial haemorrhage</div><div class=\"answer-line\">Proximal injury - Concerning for iliopsoas haemorrhage</div><div class=\"answer-line\"><strong>Tachycardia/shock</strong> – Concern for hypovolaemic shock (can occur with thigh or iliopsoas</div><div class=\"answer-line\">haemorrhage)</div><div class=\"answer-line\"><strong>(something that suggests compartment syndrome) </strong></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">inhibitor bypass agents eg recombinant factor 7</div><div class=\"answer-line\">Desmopressin</div><div class=\"answer-line\">TXA</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 58 year old man has presented with headache and sweating. He has complete quadriplegia with C6 motor and sensory levels following a motorbike accident 5 years ago.\nHis vital signs are:\n\nGCS\n\nHR\n/min\n\nBP\n190/110 mmHg\n\nSpo2\n98% room air\n\nRR\n/min Temperature 36.9 degrees 1.\nState 10 components of your assessment (history, examination or investigation). Provide\nthe relevance for each. (10 marks) 2.","parts":[{"id":"p1","label":"Part 1","prompt":"List and justify 2 components of your management. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Bowel habits – Constipation is a common cause</div><div class=\"answer-line\">Any new pressure areas – Potential cause of AD</div><div class=\"answer-line\"><strong>Bladder function/IDC function – Blocked catheter is common </strong></div><div class=\"answer-line\">Lower limb/abdominal wall infections – Potential cause</div><div class=\"answer-line\">Urinary burning/stinging/fevers as indicative of a UTI</div><div class=\"answer-line\">Recent trauma for potential missed injuries/fractures</div><div class=\"answer-line\">Previous kidney stones as indicative of increased risk of this</div><div class=\"answer-line\">Tight or restrictive clothing as can cause AD</div><div class=\"answer-line\">Testicular abnormalities noted for risk of torsion/epididymo-orchitis</div><div class=\"answer-line\">Recent sexual activity as can lead to autonomic dysreflexia</div><div class=\"answer-line\">Ingrown toenails as potential cause</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">IV Fentanyl/morphine – Reasonable dose – if painful condition precipitating dysreflexia</div><div class=\"answer-line\"><strong>GTN 400mcg q5min S/L PRN +- patch / or IV infusion </strong></div><div class=\"answer-line\"><strong>Other vasodilators acceptable </strong></div><div class=\"answer-line\">Treat the cause also OK – IDC, position change, loosen belt/pants etc</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 68 year old man has presented with 12 hours of central chest pain.\nHis ECG is provided below. (You will need to zoom the image for adequate interpretation) 1.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the ECG. Including the supportive findings. (8 marks) The patient has the following vital signs.\n\nGCS\nE3 V4 M6\n\nHR\n/min\n\nBP\n70/35 mmHg\n\nRR\n/min O2 sats 97% room air Temperature 36.2 degrees 2.\nState 3 options for management of the patient’s cardiogenic shock that you could initiate\nin the ED. For each, provide the mechanism of action involved in improving the patient’s haemodynamic status. (6 marks) Management Option Mechanism of action 3."},{"id":"p2","label":"Part 2","prompt":"State 5 additional components of your management. (5 marks)"}],"propPages":["asset:imgdb022cb52f0721cb97"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Infero-posterior <strong>STEMI</strong> complicated by <strong>complete heart block</strong> with a junctional escape rhythm (2)</td><td></td></tr><tr><td>-</td><td>Inferior STEMI - STE II, III, aVF with reciprocal STD I and aVL</td></tr><tr><td>-</td><td>RV involvement - STE III&gt;II</td></tr><tr><td>-</td><td>Posterior involvement – STD V2-V6</td></tr><tr><td>-</td><td>Complete heart block – AV dissociation</td></tr><tr><td>-</td><td>Junctional escape rhythm – regular narrow QRS complex rate 50</td></tr><tr><td>-</td><td>Biphasic/inverted T waves inferiorly – infarct likely at least 12 hours old / missed</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">IV N/S 250mL boluses aim BP&gt;90 systolic – improves RV preload</div><div class=\"answer-line\">IV adrenaline infusion 5-50mcg/min – beta 1 agonism – improves rate and contractility</div><div class=\"answer-line\">Electrical pacing eg 80mA rate 70 – increase ventricular rate</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Aspirin 300mg po</div><div class=\"answer-line\">Clopidogrel 600mg po load or ticagrelor 180mg po</div><div class=\"answer-line\">IV morphine 2.5mg aliquots until pain settled (or similar)</div><div class=\"answer-line\">Heparin – either unfractionated 5000U bolus or clexane with doses 30mg iv then 1mg/kg SC</div><div class=\"answer-line\"><strong>Urgent cardiology referral to discuss timing of cath </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 60 year old man has presented with a 2 week history of increasing lethargy, poor appetite, nausea and generalised weakness. He has a background of metastatic melanoma and is currently receiving combination intravenous immunotherapy (nivolumab + ipilimumab). 1.\nList 4 causes of his presentation related to immunotherapy. For each, state a key\ninvestigative finding. (4 marks) His initial venous blood gas shows an ionised calcium of 3.25 mmol/L (ref range 1.15-1.32 mmol/L). 2. List 4 potential causes of his hypercalcaemia. For each, state a key investigative finding. (4 marks) 3.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 potential management options for his hypercalcaemia. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Addison’s disease from adrenal inflammation – low cortisol</div><div class=\"answer-line\">Thyroiditis – accept either hypo or hyperthyroidism – TSH / T3/T4</div><div class=\"answer-line\">Nephritis – raised urea/create</div><div class=\"answer-line\">Sepsis – any source due to immunosuppression</div><div class=\"answer-line\">Other inflammatory conditions acceptable eg colitis</div><div class=\"answer-line\">2.</div><div class=\"answer-line\">Osteolytic metastases – lesions seen on x-ray / CT /MRI / bone scan</div><div class=\"answer-line\">PTHrP secretion (humoral hyperCa of malignancy) – can measure PTHrP</div><div class=\"answer-line\">Tumour production vitD – vitD levels</div><div class=\"answer-line\">Primary hyperparathyroidism – raised PTH</div><div class=\"answer-line\">Also accept chronic renal failure – raised urea/create</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">IV fluid – normal saline 1L stat</div><div class=\"answer-line\">Bisphosphonate Rx eg zoledronic acid</div><div class=\"answer-line\">Calcitonin</div><div class=\"answer-line\">Steroids eg prednisone</div><div class=\"answer-line\">Also mab - denosumab</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 24 year old man has presented following a single stab wound to the left side of his chest. His chest x-ray is provided below. 1. Describe and interpret the chest x-ray. (4 marks)\nHis vital signs are:\n\nGCS\nE4 V4 M6\n\nHR\n140 /min\n\nBP\n70/40 mmHg\n\nRR\n/min O2 sats 88% 15L O2 via non-rebreather mask Temperature 36.0 degrees He is severely agitated.","parts":[{"id":"p2","label":"Part 2","prompt":"State 4 components of your management including rationale. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 key investigations you would perform. Provide justification for each. (4 marks)"}],"propPages":["asset:img5476533bcd0f48b6ec"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Veiled left hemithorax</div><div class=\"answer-line\">Large rim blood around lung edge – increased opacity</div><div class=\"answer-line\">Midline shift to right</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Control – small dose ketamine 20mg IV</td><td><strong>Transfusion</strong> – O neg blood 1 unit aiming for systolic 80mmHg, repeat if needed</td></tr><tr><td>Intubation – optimise pre-oxygenation</td><td>Left ICC insertion large bore</td></tr><tr><td>3.</td><td><strong>FAST scan </strong>– exclude pericardial tamponade requiring thoracotomy</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 55 year old woman has presented with 24 hours of reduced colostomy output following a left hemicolectomy 6 months prior for colorectal cancer. She is complaining of nausea and intermittent crampy abdominal pain.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 differential diagnoses for her presentation. For each, provide a cardinal feature of your history or examination. (8 marks) Diagnosis Feature of history or examination"},{"id":"p2","label":"Part 2","prompt":"List 4 investigations you would perform. Provide justification for each. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Parastomal hernia – visible hernia adjacent to stoma on examination</td><td>Stomal stricture – unable to admit finger</td></tr><tr><td>Bowel obstruction from adhesions – previous similar episodes that have settled spontaneously or</td><td>operative reports</td></tr><tr><td>Constipation – high fibre diet, solid faeces preceding blockage, minimal fluid intake</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>CT abdomen – identify point of obstruction, exclude closed loop obstruction from adhesion that will</td><td>require operation</td></tr><tr><td>Electrolytes – exclude low K from third space losses</td><td>Renal function – pre-renal AKI from dehydration due to third space losses</td></tr><tr><td>Coags or G+H – pre-op measures</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 45 year old man has presented with right upper quadrant abdominal pain and fevers.\nHis liver function tests are provided below. Bilirubin 272 (<20) Bili (conj) 208 (<4) ALP 374 (35 - 140) GGT 2680 (<38) ALT 184 (<34) AST 325 (<31) LD 285 (107 - 207)","parts":[{"id":"p1","label":"Part 1","prompt":"State the likely diagnosis, including supporting abnormalities. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"State 3 features of your history. Explain how each will influence management. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 3 features of your examination. Explain how each will influence management.\n(3 marks)"},{"id":"p4","label":"Part 4","prompt":"State 3 investigations you might perform. Provide justification for each. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>Ascending cholangitis </strong>due to biliary obstruction</div><div class=\"answer-line\">Raised bilirubin, mostly conjugated</div><div class=\"answer-line\">GGT and ALP more elevated than AST/ALT consistent with obstruction rather than hepatocellular</div><div class=\"answer-line\">pattern</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Previous biliary surgery – eg strictures / stents that could be blocked</div><div class=\"answer-line\">Hx gallstones – recurrent stones</div><div class=\"answer-line\">Symptoms suggestive of malignancy eg pancreatic – weight loss, anorexia, night sweats</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Vital signs</strong> – shock with sepsis requiring resuscitation</div><div class=\"answer-line\">Examine for abdominal mass of malignancy</div><div class=\"answer-line\">RUQ tenderness in cholangitis</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>USS biliary tree – identify obstruction ?stone requiring stent</td><td>CT abdo – to exclde pancreatic cancer when no other obvious cause identified</td></tr><tr><td>BC – identify organism for downstream rationalisation of Abs</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 64 year old woman has presented with sudden onset of visual loss to her left eye.\nA clinical photograph of her retina, seen on fundoscopy, is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State the diagnosis, including 2 supportive features from the photograph. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"State 4 key features of your examination, including justification for each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"List and justify 4 investigations you would perform. (4 marks)"}],"propPages":["asset:imga5582afbd5909f1b2a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Central retinal artery occlusion</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Pale ischaemic retina</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Cherry red spot at fovea</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>VA –</strong> define severity of retinal damage</td><td>RAPD – if present will suggest severe retinal injury</td></tr><tr><td>Pulse for AF – embolic cause</td><td>Carotid bruit – for embolic cause</td></tr><tr><td>BP – hypertension a modifiable risk factor</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">ECG – exclude AF causing embolus</div><div class=\"answer-line\">Carotid doppler- looking for stenosis that might require surgery</div><div class=\"answer-line\">CT head – for identification of other strokes</div><div class=\"answer-line\">CTA – carotids as above</div><div class=\"answer-line\">Bloods – eg TFTs if in AF, lipids modifiable</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 6 month old boy with known Tetralogy of Fallot has been brought to ED with sudden onset\ncyanosis, tachypnoea and irritability.","parts":[{"id":"p1","label":"Part 1","prompt":"List the 4 anatomical abnormalities in Tetralogy of Fallot. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"State 8 potential treatment measures you might institute. Provide the rationale for each.\n(8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">VSD</div><div class=\"answer-line\">Over-riding aorta</div><div class=\"answer-line\">Pulmonary stenosis</div><div class=\"answer-line\">RV hypertrophy</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Minimise distress using parents/calm environment – decrease oxygen demand</td><td>Flex knees to chest – increase SVR and reduce R to L shunt</td></tr><tr><td>High-flow 100% oxygen – pulmonary vasodilator effect, reduces R to L</td><td>IV morphine 0.1mg/kg – reduce agitation and catecholamine driven RVOT spasm</td></tr><tr><td>IV n.saline bolus 10mL/kg – increases preload, promoting better RV outflow</td><td>IV propranolol – HR reduction</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 4 year old girl has fallen on her outstretched arm while in the playground. She is complaining of right elbow pain and refusing to move her arm. You have ordered an elbow x-ray.","parts":[{"id":"p1","label":"Part 1","prompt":"List the ossification centres of the paediatric elbow and state the usual age that they appear. (6 marks) The x-ray is provided below."},{"id":"p2","label":"Part 2","prompt":"Interpret the x-ray, including the abnormalities seen. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 3 components of your management. (3 marks)"}],"propPages":["asset:imgaa359bfb5aeadb8236"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Capitellum – 1</div><div class=\"answer-line\">Radial head – 3</div><div class=\"answer-line\">Medial epicondyle – 5</div><div class=\"answer-line\">Trochlear – 7</div><div class=\"answer-line\">Olecranon – 9</div><div class=\"answer-line\">Lateral epicondyle - 11</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Lateral epicondyle fracture</div><div class=\"answer-line\">Enlarged anterior fat pad “sail sign”</div><div class=\"answer-line\">Fracture line through lateral humerus, non-displaced</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Analgesia – something appropriate</div><div class=\"answer-line\">Long arm plaster</div><div class=\"answer-line\">Outpatient orthopaedic follow up</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
